package main

import (
	"bufio"
	"fmt"
	"io"
	"net"
	"os"
	"regexp"
	"strings"
)

const (
	bannerHashLine = "##################################################################"
	bannerTextLine = "# Content under this line is handled by hostctl. DO NOT EDIT."
)

var profileHeaderRe = regexp.MustCompile(`# profile\.(on|off)\s+([a-z0-9._\-\s]+)`)

type routeEntry struct {
	IP   string
	Host string
}

type Profile struct {
	Name    string
	Status  string
	IPOrder []string
	Routes  map[string][]string
}

func newProfile(name, status string) *Profile {
	if status == "" {
		status = "on"
	}
	return &Profile{Name: name, Status: status, Routes: map[string][]string{}}
}

func (p *Profile) AddRoute(ip, host string) {
	if p.Routes == nil {
		p.Routes = map[string][]string{}
	}
	if _, ok := p.Routes[ip]; !ok {
		p.IPOrder = append(p.IPOrder, ip)
	}
	for _, existing := range p.Routes[ip] {
		if existing == host {
			return
		}
	}
	p.Routes[ip] = append(p.Routes[ip], host)
}

func (p *Profile) RemoveDomain(host string) {
	if p == nil {
		return
	}
	newOrder := make([]string, 0, len(p.IPOrder))
	for _, ip := range p.IPOrder {
		var kept []string
		for _, existing := range p.Routes[ip] {
			if existing != host {
				kept = append(kept, existing)
			}
		}
		if len(kept) > 0 {
			p.Routes[ip] = kept
			newOrder = append(newOrder, ip)
		} else {
			delete(p.Routes, ip)
		}
	}
	p.IPOrder = newOrder
}

func (p *Profile) IsEmpty() bool {
	for _, ip := range p.IPOrder {
		if len(p.Routes[ip]) > 0 {
			return false
		}
	}
	return true
}

func (p *Profile) Entries() []routeEntry {
	var entries []routeEntry
	for _, ip := range p.IPOrder {
		for _, host := range p.Routes[ip] {
			entries = append(entries, routeEntry{IP: ip, Host: host})
		}
	}
	return entries
}

type HostsFile struct {
	Path         string
	DefaultLines []string
	ProfileNames []string
	Profiles     map[string]*Profile
}

func loadHostsFile(path string) (*HostsFile, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	return parseHostsFile(f, path), nil
}

// tokenizeRoute converts a raw line into route fields (IP followed by hosts),
// honouring "# ..." comments in the way the reference tool does: a leading
// standalone '#' token is skipped, any other '#' starts an inline comment and
// truncates the token that contains it.
func tokenizeRoute(line string) []string {
	raw := strings.Fields(line)
	var fields []string
	for i, tok := range raw {
		if tok == "#" {
			if i == 0 {
				continue
			}
			break
		}
		if idx := strings.Index(tok, "#"); idx >= 0 {
			if idx > 0 {
				fields = append(fields, tok[:idx])
			}
			break
		}
		fields = append(fields, tok)
	}
	return fields
}

func parseRouteLine(line string) (net.IP, []string, bool) {
	fields := tokenizeRoute(line)
	if len(fields) < 2 {
		return nil, nil, false
	}
	ip := net.ParseIP(fields[0])
	if ip == nil {
		return nil, nil, false
	}
	return ip, fields[1:], true
}

func parseHostsFile(r io.Reader, path string) *HostsFile {
	hf := &HostsFile{Path: path, Profiles: map[string]*Profile{}}
	scanner := bufio.NewScanner(r)
	var current *Profile
	inProfile := false
	for scanner.Scan() {
		raw := scanner.Text()
		if m := profileHeaderRe.FindStringSubmatch(raw); m != nil {
			name := strings.TrimSpace(m[2])
			prof := newProfile(name, m[1])
			hf.Profiles[name] = prof
			hf.ProfileNames = append(hf.ProfileNames, name)
			current = prof
			inProfile = true
			continue
		}
		if strings.Contains(strings.ToLower(raw), "# end") {
			current = nil
			inProfile = false
			continue
		}
		if inProfile {
			if ip, hosts, ok := parseRouteLine(raw); ok && current != nil {
				ipStr := ip.String()
				for _, host := range hosts {
					current.AddRoute(ipStr, host)
				}
			}
			continue
		}
		if strings.Contains(raw, bannerTextLine) {
			// The previous line is expected to be the banner hash line and
			// the next line is consumed unconditionally (matching the
			// reference parser, including its panic on an empty file whose
			// first line is the banner text).
			hf.DefaultLines = hf.DefaultLines[:len(hf.DefaultLines)-1]
			scanner.Scan()
			continue
		}
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			if n := len(hf.DefaultLines); n > 0 && hf.DefaultLines[n-1] == "" {
				continue
			}
			hf.DefaultLines = append(hf.DefaultLines, "")
			continue
		}
		if ip, hosts, ok := parseRouteLine(raw); ok {
			prefix := ""
			if strings.HasPrefix(raw, "#") {
				prefix = "# "
			}
			hf.DefaultLines = append(hf.DefaultLines, fmt.Sprintf("%s%s %s", prefix, ip.String(), hosts[0]))
			continue
		}
		hf.DefaultLines = append(hf.DefaultLines, trimmed)
	}
	return hf
}

func (hf *HostsFile) ensureProfile(name string) *Profile {
	if p, ok := hf.Profiles[name]; ok {
		return p
	}
	p := newProfile(name, "on")
	if hf.Profiles == nil {
		hf.Profiles = map[string]*Profile{}
	}
	hf.Profiles[name] = p
	hf.ProfileNames = append(hf.ProfileNames, name)
	return p
}

func (hf *HostsFile) replaceProfile(name string, entries []routeEntry) *Profile {
	p := newProfile(name, "on")
	if hf.Profiles == nil {
		hf.Profiles = map[string]*Profile{}
	}
	if _, ok := hf.Profiles[name]; !ok {
		hf.ProfileNames = append(hf.ProfileNames, name)
	}
	hf.Profiles[name] = p
	for _, e := range entries {
		p.AddRoute(e.IP, e.Host)
	}
	return p
}

func (hf *HostsFile) deleteProfile(name string) {
	delete(hf.Profiles, name)
	names := make([]string, 0, len(hf.ProfileNames))
	for _, n := range hf.ProfileNames {
		if n != name {
			names = append(names, n)
		}
	}
	hf.ProfileNames = names
}

func (hf *HostsFile) hasProfile(name string) bool {
	_, ok := hf.Profiles[name]
	return ok
}

func (hf *HostsFile) Flush() error {
	var b strings.Builder
	def := hf.DefaultLines
	for len(def) > 0 && def[len(def)-1] == "" {
		def = def[:len(def)-1]
	}
	for _, line := range def {
		b.WriteString(line)
		b.WriteByte('\n')
	}
	b.WriteString("\n" + bannerHashLine + "\n" + bannerTextLine + "\n" + bannerHashLine + "\n")
	for _, name := range hf.ProfileNames {
		p := hf.Profiles[name]
		if p == nil {
			continue
		}
		b.WriteString(fmt.Sprintf("\n# profile.%s %s\n", p.Status, p.Name))
		prefix := ""
		if p.Status == "off" {
			prefix = "# "
		}
		for _, e := range p.Entries() {
			b.WriteString(fmt.Sprintf("%s%s %s\n", prefix, e.IP, e.Host))
		}
		b.WriteString("# end\n")
	}
	if err := os.WriteFile(hf.Path, []byte(b.String()), 0644); err != nil {
		return err
	}
	// Reload so later rendering reflects the file as re-parsed.
	if reloaded, err := loadHostsFile(hf.Path); err == nil {
		*hf = *reloaded
	}
	return nil
}

func (hf *HostsFile) defaultRows() []Row {
	var rows []Row
	for _, line := range hf.DefaultLines {
		ip, hosts, ok := parseRouteLine(line)
		if !ok {
			continue
		}
		status := "on"
		if strings.HasPrefix(line, "#") {
			status = "off"
		}
		rows = append(rows, Row{Profile: "default", Status: status, IP: ip.String(), Host: hosts[0]})
	}
	return rows
}

func profileRows(p *Profile) []Row {
	var rows []Row
	for _, e := range p.Entries() {
		rows = append(rows, Row{Profile: p.Name, Status: p.Status, IP: e.IP, Host: e.Host})
	}
	return rows
}

// listGroups returns groups (one per profile) of rows in file order. A
// statusFilter of "" means no status filtering.
func (hf *HostsFile) listGroups(filter []string, statusFilter string) [][]Row {
	var groups [][]Row
	includeDefault := len(filter) == 0 || containsString(filter, "default")
	if includeDefault {
		if rows := hf.defaultRows(); len(rows) > 0 {
			groups = append(groups, rows)
		}
	}
	for _, name := range hf.ProfileNames {
		p := hf.Profiles[name]
		if p == nil {
			continue
		}
		if len(filter) > 0 && !containsString(filter, p.Name) {
			continue
		}
		if statusFilter != "" && p.Status != statusFilter {
			continue
		}
		if rows := profileRows(p); len(rows) > 0 {
			groups = append(groups, rows)
		}
	}
	return groups
}

func (hf *HostsFile) statusRows(filter []string) []Row {
	var rows []Row
	for _, name := range hf.ProfileNames {
		p := hf.Profiles[name]
		if p == nil {
			continue
		}
		if len(filter) > 0 && !containsString(filter, p.Name) {
			continue
		}
		rows = append(rows, Row{Profile: p.Name, Status: p.Status})
	}
	return rows
}

func containsString(list []string, s string) bool {
	for _, item := range list {
		if item == s {
			return true
		}
	}
	return false
}

func parseSourceRoutes(r io.Reader) []routeEntry {
	var entries []routeEntry
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		ip, hosts, ok := parseRouteLine(scanner.Text())
		if !ok {
			continue
		}
		ipStr := ip.String()
		for _, host := range hosts {
			entries = append(entries, routeEntry{IP: ipStr, Host: host})
		}
	}
	return entries
}
