package main

import (
	"encoding/json"
	"regexp"
	"strings"

	"github.com/mattn/go-runewidth"
)

type Row struct {
	Profile string
	Status  string
	IP      string
	Host    string
}

var ansiRe = regexp.MustCompile("\x1b\\[[0-9;:]*[A-Za-z]")

func displayWidth(s string) int {
	return runewidth.StringWidth(ansiRe.ReplaceAllString(s, ""))
}

func padRight(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	return s + strings.Repeat(" ", width-w)
}

func centerPad(s string, width int) string {
	w := displayWidth(s)
	if w >= width {
		return s
	}
	left := (width - w) / 2
	right := width - w - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func rowCells(row Row, columns []string) []string {
	var cells []string
	for _, col := range columns {
		switch col {
		case "profile":
			cells = append(cells, row.Profile)
		case "status":
			cells = append(cells, row.Status)
		case "ip":
			cells = append(cells, row.IP)
		case "domain":
			cells = append(cells, row.Host)
		}
	}
	return cells
}

func flattenGroups(groups [][]Row) []Row {
	var rows []Row
	for _, g := range groups {
		rows = append(rows, g...)
	}
	return rows
}

// renderGroups renders grouped rows according to the output type.
func renderGroups(groups [][]Row, columns []string, outType string) string {
	if outType == "json" {
		return renderJSON(flattenGroups(groups))
	}
	// Convert grouped rows to cells.
	type groupCells struct {
		rows [][]string
	}
	var converted [][][]string
	var allCells [][]string
	for _, g := range groups {
		var gc [][]string
		for _, row := range g {
			cells := rowCells(row, columns)
			gc = append(gc, cells)
			allCells = append(allCells, cells)
		}
		if len(gc) > 0 {
			converted = append(converted, gc)
		}
	}
	return renderTable(converted, allCells, headersFor(columns), outType)
}

func renderFlatRows(rows []Row, columns []string, outType string) string {
	if outType == "json" {
		return renderJSON(rows)
	}
	var converted [][][]string
	var allCells [][]string
	var gc [][]string
	for _, row := range rows {
		cells := rowCells(row, columns)
		gc = append(gc, cells)
		allCells = append(allCells, cells)
	}
	if len(gc) > 0 {
		converted = append(converted, gc)
	}
	return renderTable(converted, allCells, headersFor(columns), outType)
}

func headersFor(columns []string) []string {
	headers := make([]string, len(columns))
	for i, col := range columns {
		headers[i] = strings.ToUpper(col)
	}
	return headers
}

func renderJSON(rows []Row) string {
	data, _ := json.Marshal(rows)
	return string(data) + "\n"
}

func renderTable(groups [][][]string, allCells [][]string, headers []string, outType string) string {
	if len(allCells) == 0 {
		return ""
	}
	hasAnyCell := false
	for _, row := range allCells {
		if len(row) > 0 {
			hasAnyCell = true
			break
		}
	}
	if !hasAnyCell {
		return ""
	}
	widths := make([]int, len(headers))
	for i, h := range headers {
		widths[i] = displayWidth(h)
	}
	for _, row := range allCells {
		for i, cell := range row {
			if i >= len(widths) {
				continue
			}
			if w := displayWidth(cell); w > widths[i] {
				widths[i] = w
			}
		}
	}

	borderLine := func(left, mid, right string) string {
		var b strings.Builder
		b.WriteString(left)
		for i, w := range widths {
			b.WriteString(strings.Repeat("-", w+2))
			if i == len(widths)-1 {
				b.WriteString(right)
			} else {
				b.WriteString(mid)
			}
		}
		b.WriteByte('\n')
		return b.String()
	}
	formatRow := func(cells []string, isHeader bool) string {
		var b strings.Builder
		b.WriteString("|")
		for i, cell := range cells {
			if i >= len(widths) {
				break
			}
			b.WriteByte(' ')
			if isHeader {
				b.WriteString(centerPad(cell, widths[i]))
			} else {
				b.WriteString(padRight(cell, widths[i]))
			}
			b.WriteString(" |")
		}
		b.WriteByte('\n')
		return b.String()
	}

	var out strings.Builder
	switch outType {
	case "raw":
		// Header: tab-joined, padded, last cell gets one extra space.
		for i, h := range headers {
			out.WriteString(padRight(h, widths[i]))
			if i == len(headers)-1 {
				out.WriteByte(' ')
			} else {
				out.WriteByte('\t')
			}
		}
		out.WriteByte('\n')
		for _, group := range groups {
			for _, row := range group {
				for i, cell := range row {
					if i >= len(widths) {
						break
					}
					out.WriteString(padRight(cell, widths[i]))
					out.WriteByte('\t')
				}
				out.WriteByte('\n')
			}
		}
	case "markdown":
		out.WriteString(formatRow(headers, true))
		sep := borderLine("|", "|", "|")
		out.WriteString(sep)
		for gi, group := range groups {
			if gi > 0 {
				out.WriteString(sep)
			}
			for _, row := range group {
				out.WriteString(formatRow(row, false))
			}
		}
	default: // table
		border := borderLine("+", "+", "+")
		out.WriteString(border)
		out.WriteString(formatRow(headers, true))
		out.WriteString(border)
		for gi, group := range groups {
			if gi > 0 {
				out.WriteString(border)
			}
			for _, row := range group {
				out.WriteString(formatRow(row, false))
			}
		}
		out.WriteString(border)
	}
	return out.String()
}
