package docker

import (
	"context"
	"crypto/tls"
	"crypto/x509"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/url"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"syscall"
	"time"

	"hostctl/internal/docker/types"
)

const defaultAPIVersion = "1.42"

type Client struct {
	daemonHost string
	baseURL    string
	apiVersion string
	httpClient *http.Client
}

func versionLessThan(v, other string) bool {
	return compareVersion(v, other) < 0
}

func compareVersion(v, other string) int {
	a := strings.Split(v, ".")
	b := strings.Split(other, ".")
	n := len(a)
	if len(b) > n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		var ai, bi int
		if i < len(a) {
			ai, _ = strconv.Atoi(a[i])
		}
		if i < len(b) {
			bi, _ = strconv.Atoi(b[i])
		}
		if ai < bi {
			return -1
		}
		if ai > bi {
			return 1
		}
	}
	return 0
}

func NewClientFromEnv() (*Client, error) {
	host := os.Getenv("DOCKER_HOST")
	if host == "" {
		host = "unix:///var/run/docker.sock"
	}
	apiVersion := os.Getenv("DOCKER_API_VERSION")
	if apiVersion == "" {
		apiVersion = defaultAPIVersion
	}
	if !strings.Contains(host, "://") {
		return nil, fmt.Errorf("unable to parse docker host `%s`", host)
	}
	u, err := url.Parse(host)
	if err != nil {
		return nil, err
	}

	transport := &http.Transport{}
	scheme := "http"
	baseHost := u.Host
	basePath := strings.TrimSuffix(u.Path, "/")

	// TLS material, following the environment-based setup of the Docker
	// client libraries (DOCKER_CERT_PATH / DOCKER_TLS_VERIFY).
	certPath := os.Getenv("DOCKER_CERT_PATH")
	tlsVerify := os.Getenv("DOCKER_TLS_VERIFY")
	if certPath != "" && u.Scheme != "unix" && u.Scheme != "npipe" {
		tlsConfig := &tls.Config{}
		if tlsVerify != "" {
			caFile := filepath.Join(certPath, "ca.pem")
			data, err := os.ReadFile(caFile)
			if err != nil {
				return nil, fmt.Errorf("could not read CA certificate %q: %v", caFile, err)
			}
			pool := x509.NewCertPool()
			pool.AppendCertsFromPEM(data)
			tlsConfig.RootCAs = pool
			scheme = "https"
		} else {
			certFile := filepath.Join(certPath, "cert.pem")
			keyFile := filepath.Join(certPath, "key.pem")
			cert, err := tls.LoadX509KeyPair(certFile, keyFile)
			if err != nil {
				return nil, fmt.Errorf("Could not load X509 key pair: %v", err)
			}
			tlsConfig.Certificates = []tls.Certificate{cert}
		}
		transport.TLSClientConfig = tlsConfig
	}

	baseURL := ""
	switch u.Scheme {
	case "unix":
		socketPath := strings.TrimPrefix(host, "unix://")
		transport.DialContext = func(ctx context.Context, _, _ string) (net.Conn, error) {
			var d net.Dialer
			return d.DialContext(ctx, "unix", socketPath)
		}
		baseURL = "http://unix.sock"
	case "npipe":
		return nil, fmt.Errorf("unable to parse docker host `%s`", host)
	default:
		baseURL = scheme + "://" + baseHost + basePath
		_ = time.Now
	}

	return &Client{
		daemonHost: host,
		baseURL:    baseURL,
		apiVersion: apiVersion,
		httpClient: &http.Client{Transport: transport},
	}, nil
}

func isConnectionFailed(err error) bool {
	var opErr *net.OpError
	if errors.As(err, &opErr) {
		var dnsErr *net.DNSError
		if errors.As(err, &dnsErr) {
			return false
		}
		var errno syscall.Errno
		if errors.As(err, &errno) {
			return true
		}
		if os.IsNotExist(err) {
			return true
		}
	}
	return false
}

func (c *Client) filtersQuery(filters map[string][]string) string {
	var encoded string
	if versionLessThan(c.apiVersion, "1.22") {
		data, _ := json.Marshal(filters)
		encoded = string(data)
	} else {
		obj := map[string]map[string]bool{}
		for key, values := range filters {
			obj[key] = map[string]bool{}
			for _, v := range values {
				obj[key][v] = true
			}
		}
		data, _ := json.Marshal(obj)
		encoded = string(data)
	}
	values := url.Values{}
	values.Set("filters", encoded)
	return values.Encode()
}

func (c *Client) versionedPath(p string) string {
	return fmt.Sprintf("/v%s%s", strings.TrimPrefix(c.apiVersion, "v"), p)
}

func (c *Client) doGet(p, query string) (*http.Response, string, error) {
	fullURL := c.baseURL + c.versionedPath(p)
	if query != "" {
		fullURL += "?" + query
	}
	resp, err := c.httpClient.Get(fullURL)
	if err != nil {
		if isConnectionFailed(err) {
			return nil, fullURL, fmt.Errorf("Cannot connect to the Docker daemon at %s. Is the docker daemon running?", c.daemonHost)
		}
		return nil, fullURL, fmt.Errorf("error during connect: %v", err)
	}
	if resp.StatusCode >= 400 {
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		if len(strings.TrimSpace(string(body))) == 0 {
			return nil, fullURL, fmt.Errorf("request returned %s for API route and version %s, check if the server supports the requested API version", resp.Status, fullURL)
		}
		var payload struct {
			Message string `json:"message"`
		}
		if jerr := json.Unmarshal(body, &payload); jerr != nil {
			return nil, fullURL, fmt.Errorf("Error reading JSON: %v", jerr)
		}
		return nil, fullURL, fmt.Errorf("Error response from daemon: %s", payload.Message)
	}
	return resp, fullURL, nil
}

