// ResolveNetworkID finds a network by name or ID and returns its ID.
func (c *Client) ResolveNetworkID(nameOrID string) (string, error) {
	networks, err := c.NetworkList()
	if err != nil {
		return "", err
	}
	for _, n := range networks {
		if n.Name == nameOrID || n.ID == nameOrID {
			return n.ID, nil
		}
	}
