actions.command:
cat > commands.go <<'EOF'
package main

import (
	"errors"
	"fmt"
	"io"
	"net"
	"os"
	"os/signal"
	"path/filepath"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/spf13/cobra"
)

type appOptions struct {
	hostFile string
	out      string
	rawOut   bool
	noColor  bool
	quiet    bool
	columns  []string
}

func (o *appOptions) outType() string {
	if o.rawOut {
		return "raw"
	}
	switch o.out {
	case "raw", "markdown", "json":
		return o.out
	default:
		return "table"
	}
}

func (o *appOptions) effectiveColumns() []string {
	if len(o.columns) == 0 {
		return []string{"profile", "status", "ip", "domain"}
	}
	return o.columns
}

func (o *appOptions) success(w io.Writer, text string) {
	if o.quiet {
		return
	}
	fmt.Fprintf(w, "[%s] %s\n\n", successSymbol(), text)
}

func (o *appOptions) renderProfileGroups(w io.Writer, hf *HostsFile, filter []string, extraNewline bool) {
	if o.quiet {
		return
	}
	fmt.Fprint(w, renderGroups(hf.listGroups(filter, ""), o.effectiveColumns(), o.outType()))
	if extraNewline {
		fmt.Fprintln(w)
	}
}

var (
	errMissingProfile  = errors.New("missing profile name")
	errOnlyOneProfile  = errors.New("specify only one profile")
	errDefaultProfile  = errors.New("'default' profile should not be handled by hostctl")
	errUnknownProfile  = errors.New("unknown profile name")
	errAllWithArgs     = errors.New("args must be empty with --all flag")
	errNoProfiles      = errors.New("there are no profiles")
)

func validateSingleProfile(_ *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	if len(args) > 1 {
		return errOnlyOneProfile
	}
	if args[0] == "default" {
		return errDefaultProfile
	}
	return nil
}

func validateMultiProfile(getAll func() bool) func(*cobra.Command, []string) error {
	return func(_ *cobra.Command, args []string) error {
		if getAll != nil {
			if getAll() && len(args) > 0 {
				return errAllWithArgs
			}
			if !getAll() && len(args) == 0 {
				return errMissingProfile
			}
		} else if len(args) == 0 {
			return errMissingProfile
		}
		if containsString(args, "default") {
			return errDefaultProfile
		}
		return nil
	}
}

func validateDomainsProfile(_ *cobra.Command, args []string) error {
	if len(args) == 0 {
		return errMissingProfile
	}
	if args[0] == "default" {
		return errDefaultProfile
	}
	return nil
}

func defaultHostsPath() string {
	if runtime.GOOS == "windows" {
		return "C:/Windows/System32/Drivers/etc/hosts"
	}
	return "/etc/hosts"
}

// hasStdinInput reports whether data is being piped/redirected into stdin.
func hasStdinInput() bool {
	fi, err := os.Stdin.Stat()
	if err != nil {
		return false
	}
	return fi.Mode()&os.ModeNamedPipe != 0 || fi.Size() > 0
}

func openSource(from string) (io.ReadCloser, error) {
	if hasStdinInput() {
		return io.NopCloser(os.Stdin), nil
	}
	return os.Open(from)
}

func (o *appOptions) waitAndRollback(w io.Writer, wait time.Duration, verb string, names string, rollback func() error) error {
	if wait < 0 {
		return nil
	}
	if !o.quiet {
		var msg string
		if wait == 0 {
			msg = fmt.Sprintf("Waiting until ctrl+c to %s from profile '%s'", verb, names)
		} else {
			msg = fmt.Sprintf("Waiting for %s or ctrl+c to %s from profile '%s'", wait.String(), verb, names)
		}
		fmt.Fprintf(w, "[%s] %s\n\n\n", infoSymbol(), msg)
	}
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, os.Interrupt, syscall.SIGTERM)
	if wait == 0 {
		<-sigChan
	} else {
		select {
		case <-sigChan:
		case <-time.After(wait):
		}
	}
	signal.Stop(sigChan)
	fmt.Fprintln(w)
	return rollback()
}

// ---- shared action implementations (also used as wait rollbacks) ----

func (o *appOptions) doEnableDisable(w io.Writer, args []string, target string, all, only bool, isRollback bool) error {
	hf, err := loadHostsFile(o.hostFile)
	if err != nil {
		return err
	}
	opposite := "off"
	if target == "off" {
		opposite = "on"
	}
	if all {
		for _, name := range hf.ProfileNames {
			if p := hf.Profiles[name]; p != nil {
				p.Status = target
			}
		}
	} else {
		for _, name := range args {
			if !hf.hasProfile(name) {
				return errUnknownProfile
			}
		}
		for _, name := range args {
			hf.Profiles[name].Status = target
		}
		if only {
			for _, name := range hf.ProfileNames {
				if p := hf.Profiles[name]; p != nil && !containsString(args, name) {
					p.Status = opposite
				}
			}
		}
	}
	if err := hf.Flush(); err != nil {
		return err
	}
	var filter []string
	if !all {
		filter = args
	}
	if !o.quiet {
		fmt.Fprint(w, renderGroups(hf.listGroups(filter, ""), o.effectiveColumns(), o.outType()))
		if !isRollback {
			fmt.Fprintln(w)
		}
	}
	return nil
}

func (o *appOptions) doToggle(w io.Writer, args []string, isRollback bool) error {
	hf, err := loadHostsFile(o.hostFile)
	if err != nil {
		return err
	}
	for _, name := range args {
		p, ok := hf.Profiles[name]
		if !ok {
			return errUnknownProfile
		}
		if p.Status == "on" {
			p.Status = "off"
		} else {
			p.Status = "on"
		}
	}
	if err := hf.Flush(); err != nil {
		return err
	}
	if !o.quiet {
		fmt.Fprint(w, renderGroups(hf.listGroups(args, ""), o.effectiveColumns(), o.outType()))
		if !isRollback {
			fmt.Fprintln(w)
		}
	}
	return nil
}

func (o *appOptions) doRemoveProfiles(w io.Writer, args []string, all bool) error {
	hf, err := loadHostsFile(o.hostFile)
	if err != nil {
		return err
	}
	var names []string
	if all {
		if len(hf.ProfileNames) == 0 {
			return errNoProfiles
		}
		names = append(names, hf.ProfileNames...)
	} else {
		names = args
	}
	for _, name := range names {
		if !hf.hasProfile(name) {
			return errUnknownProfile
		}
		hf.deleteProfile(name)
	}
	if err := hf.Flush(); err != nil {
		return err
	}
	if !o.quiet {
		o.success(w, fmt.Sprintf("Profile(s) '%s' removed.", strings.Join(names, ", ")))
		fmt.Fprintln(w)
	}
	return nil
}

func (o *appOptions) doRemoveDomains(w io.Writer, args []string) error {
	hf, err := loadHostsFile(o.hostFile)
	if err != nil {
		return err
	}
	profileName := args[0]
	domains := args[1:]
	p, ok := hf.Profiles[profileName]
	if !ok {
		return errUnknownProfile
	}
	for _, d := range domains {
		p.RemoveDomain(d)
	}
	removedProfile := p.IsEmpty()
	if removedProfile {
		hf.deleteProfile(profileName)
	}
	if err := hf.Flush(); err != nil {
		return err
	}
	if !o.quiet {
		if removedProfile {
			o.success(w, fmt.Sprintf("Profile '%s' removed.", profileName))
		} else {
			o.success(w, fmt.Sprintf("Domains '%s' removed.", strings.Join(domains, ", ")))
		}
		fmt.Fprint(w, renderGroups(hf.listGroups([]string{profileName}, ""), o.effectiveColumns(), o.outType()))
	}
	return nil
}

func copyFile(src, dst string) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()
	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()
	_, err = io.Copy(out, in)
	return err
}

