)

// fetchContainers resolves an optional network filter and lists running
// containers from Docker.
func fetchContainers(network string) ([]dockertypes.Container, string, error) {
	client, err := dockerclient.NewClientFromEnv()
	if err != nil {
		return nil, "", err
	}
	networkID := ""
	if network != "" {
		networkID, err = client.ResolveNetworkID(network)
		if err != nil {
			return nil, "", err
		}
	}
	containers, err := client.ContainerList(networkID)
	if err != nil {
		return nil, "", err
	}
	return containers, networkID, nil
}

func containerEntries(containers []dockertypes.Container, networkID string, hostForName func(string) (string, bool)) []routeEntry {
	var entries []routeEntry
	for _, container := range containers {
		name := strings.ReplaceAll(container.Names[0], "/", "")
		host, ok := hostForName(name)
		if !ok {
			continue
		}
		for _, endpoint := range container.NetworkSettings.Networks {
			if networkID != "" && endpoint.NetworkID != networkID {
				continue
			}
			ip := net.ParseIP(endpoint.IPAddress)
			entries = append(entries, routeEntry{IP: ip.String(), Host: host})
		}
	}
	return entries
}

func (o *appOptions) doSyncDocker(w io.Writer, profileName, domain, network string) error {
	if domain == "" {
		domain = "loc"
	}
	containers, networkID, err := fetchContainers(network)
	if err != nil {
		return err
	}
	entries := containerEntries(containers, networkID, func(name string) (string, bool) {
		return fmt.Sprintf("%s.%s", name, domain), true
	})
	hf, err := loadHostsFile(o.hostFile)
	if err != nil {
		return err
	}
	hf.replaceProfile(profileName, entries)
	if err := hf.Flush(); err != nil {
		return err
	}
	o.renderProfileGroups(w, hf, []string{profileName}, true)
	return nil
}

func normalizeProjectName(name string) string {
	name = strings.ToLower(name)
	var b strings.Builder
	for _, r := range name {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' {
			b.WriteRune(r)
		}
	}
	return b.String()
}

func (o *appOptions) doSyncDockerCompose(w io.Writer, profileName string, opts composeOptions) error {
	composePath := opts.composeFile
	if composePath == "" {
		cwd, err := os.Getwd()
		if err != nil {
			return err
		}
		composePath = filepath.Join(cwd, "docker-compose.yml")
	}
	content, err := os.ReadFile(composePath)
	if err != nil {
		return err
	}
	containers, networkID, err := fetchContainers(opts.network)
	if err != nil {
		return err
	}
	services, err := dockerclient.ParseCompose(content)
	if err != nil {
		return err
	}
	projectName := opts.projectName
	if projectName == "" {
		absPath, aerr := filepath.Abs(composePath)
		if aerr != nil {
			absPath = composePath
		}
		projectName = normalizeProjectName(filepath.Base(filepath.Dir(absPath)))
